#!/usr/bin/env python3
"""Apply Stage 10 archive-dependency CI follow-up locally; no network or simulator."""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import subprocess
import tempfile
import zlib

REPO=Path('/home/lx/microduck-double-balance/workspace')
BASE='1a11f30cc7264d00dec7bce8f11449ded9164169'
TAG='stage-10-complete'
REMOTE='git@github.com:liuxue-lab/microduck-double-balance.git'
MESSAGE='Fix Stage 10 recovery archive dependencies for CI collection'
SELF_PATH='scripts/stage10_ci_fix.py'
RUNTIME_SHA='b61850afbd6fa0deccb3a23a098a910aae74bc0e9b01cca2ee0634c2d1f6ecfd'
PAYLOAD=''

def require(ok,message):
    if not ok: raise RuntimeError(message)

def sha(data): return hashlib.sha256(data).hexdigest()

def git_bytes(*args):
    return subprocess.check_output(['git','-C',str(REPO),*args])

def git(*args): return git_bytes(*args).decode().strip()

def paths(*args): return {p.decode() for p in git_bytes(*args,'-z').split(b'\0') if p}

def run(*args): subprocess.run(['git','-C',str(REPO),*args],check=True)

def safe(rel):
    rel=Path(rel)
    require(not rel.is_absolute() and '..' not in rel.parts,'Unsafe relative target')
    p=REPO/rel
    require(not any(x.is_symlink() for x in [p,*p.parents]),'Linked target preserved: '+str(p))
    require(p.resolve().is_relative_to(REPO.resolve()),'Target escapes repository')
    return p

def runtime():
    p=safe('docs/audits/stage-09-runtime-hashes.json')
    require(sha(p.read_bytes())==RUNTIME_SHA,'Frozen manifest differs')
    entries=json.loads(p.read_text());require(len(entries)==101,'Expected 101 frozen files')
    for rel,h in entries.items():require(sha(safe(rel).read_bytes())==h,'Frozen source differs: '+rel)
    return entries

def tag_state():
    require(git('cat-file','-t','refs/tags/'+TAG)=='tag','Expected existing annotated Stage 10 tag')
    require(git('rev-parse','refs/tags/'+TAG+'^{commit}')==BASE,'Stage 10 tag differs; preserved')
    return git('rev-parse','refs/tags/'+TAG)

def atomic(path,data):
    path.parent.mkdir(parents=True,exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=path.parent,delete=False) as f:
        tmp=Path(f.name);f.write(data);f.flush();os.fsync(f.fileno())
    try:
        tmp.chmod(0o644);tmp.replace(path)
    finally:tmp.unlink(missing_ok=True)

def apply(payload,verify_only=False):
    require(git('rev-parse','--show-toplevel')==str(REPO),'Use the canonical laptop checkout')
    require(git('branch','--show-current')=='double-balance','Expected double-balance branch')
    for args in [('remote','get-url','--all','origin'),('remote','get-url','--push','--all','origin')]:
        require(git(*args).splitlines()==[REMOTE],'Unexpected SSH remote; not changed')
    rows=payload['files'];allowed={r['path'] for r in rows}|{SELF_PATH}
    require(len(allowed)==len(rows)+1,'Duplicate patch targets')
    require(not (set(runtime())&allowed),'Patch would change frozen runtime')
    old_tag=tag_state();head=git('rev-parse','HEAD');already=head!=BASE
    if already:
        require(git('log','-1','--format=%s')==MESSAGE and git('rev-list','--parents','-n','1','HEAD').split()==[head,BASE],
                'Unexpected HEAD; preserve it and return the message')
        require(paths('diff','--name-only',BASE,head)==allowed,'Unexpected existing fix commit paths')
    staged=paths('diff','--cached','--name-only')
    require(staged<=allowed,'Unrelated staged work preserved')
    require(paths('diff','HEAD','--name-only')<=allowed,'Unrelated tracked work preserved')
    desired={}
    for r in rows:
        data=base64.b64decode(r['data'],validate=True)
        require(sha(data)==r['sha256'],'Embedded file SHA mismatch')
        p=safe(r['path']);actual=sha(p.read_bytes()) if p.is_file() else None
        require(not p.exists() or p.is_file(),'Non-file target preserved')
        expected=[r['sha256']] if already else [r['before_sha256'],r['sha256']]
        require(actual in expected,'Existing edit preserved: '+r['path'])
        if not already:
            tracked=git_bytes('ls-tree','HEAD','--',r['path'])
            if r['before_sha256'] is None:require(not tracked,'New target already tracked: '+r['path'])
            else:require(bool(tracked) and sha(git_bytes('show','HEAD:'+r['path']))==r['before_sha256'],'Baseline bytes differ: '+r['path'])
        desired[r['path']]=data
    desired[SELF_PATH]=Path(__file__).read_bytes()
    target=safe(SELF_PATH)
    require(not target.exists() or (target.is_file() and target.read_bytes()==desired[SELF_PATH]),'Existing fix tool differs; preserved')
    if not already:require(not git_bytes('ls-tree','HEAD','--',SELF_PATH),'Fix tool already tracked at base')
    for rel,data in desired.items():
        if rel in staged:require(git_bytes('show',':'+rel)==data,'Staged target differs; preserved: '+rel)
        if already:
            require(safe(rel).is_file() and safe(rel).read_bytes()==data and git_bytes('show','HEAD:'+rel)==data,
                    'Existing fix bytes differ: '+rel)
    if verify_only:
        print('Stage10CIFix=VERIFIED_ONLY; no writes, commits or tag changes');return None
    if not already:
        for rel,data in desired.items():
            p=safe(rel)
            if not p.is_file() or p.read_bytes()!=data:atomic(p,data)
        require(git('rev-parse','HEAD')==BASE,'HEAD changed; files preserved, no commit')
        runtime();run('add','--',*sorted(desired))
        require(paths('diff','--cached','--name-only')==allowed,'Unexpected index; no commit')
        for rel,data in desired.items():require(git_bytes('show',':'+rel)==data,'Staged bytes differ: '+rel)
        run('diff','--cached','--check')
        run('commit','-m',MESSAGE)
        head=git('rev-parse','HEAD')
        require(git('rev-list','--parents','-n','1','HEAD').split()==[head,BASE],'Unexpected commit parent')
    require(paths('diff','--name-only',BASE,head)==allowed,'Unexpected changed paths')
    for rel,data in desired.items():
        require(git_bytes('show','HEAD:'+rel)==data and safe(rel).read_bytes()==data,'Post-commit bytes differ: '+rel)
    require(not paths('diff','HEAD','--name-only') and not paths('diff','--cached','--name-only'),'Tracked/index edits remain')
    runtime();require(tag_state()==old_tag,'Original Stage 10 tag changed')
    print('Stage10CIFix=LOCAL_COMMIT_COMPLETE_SSH_PUSH_AND_REMOTE_CI_PENDING')
    print('Stage10CIFixCommit='+head)
    print('Stage10Tag=UNCHANGED; '+BASE)
    print('Stage10NewPPO=0; Simulation=0; Cloud=OFF_CONFIRMED_BY_USER')
    print('Next: cd /home/lx/microduck-double-balance/workspace')
    print('git push origin double-balance')
    print('Do not push or move the Stage 10 tag; inspect only the new commit CI result.')
    return head

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--verify-only',action='store_true')
    args=parser.parse_args();payload=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    if args.verify_only:apply(payload,True)
    else:
        import fcntl
        lock=Path(tempfile.gettempdir())/('microduck-stage10-ci-fix-'+sha(str(REPO).encode())[:16]+'.lock')
        fd=os.open(lock,os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
        with os.fdopen(fd,'w') as f:
            try:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:raise RuntimeError('Another Stage 10 CI fix is running')
            apply(payload)

if __name__=='__main__':
    try:main()
    except Exception as exc:
        print('Stage10CIFix=STOPPED; '+type(exc).__name__+': '+str(exc));raise SystemExit(1)
